<?php
namespace App\Http\Controllers\Api\V1; use App\Http\Controllers\Controller; use App\Models\Device; use Illuminate\Http\Request;
class DeviceController extends Controller { public function index(Request $r){$u=$r->attributes->get('app_user');return response()->json(['ok'=>true,'devices'=>Device::where('user_id',$u->id)->latest('last_seen_at')->get()]);} public function register(Request $r){$d=$r->validate(['device_id'=>'required|string|max:120','platform'=>'required|string|max:30','fcm_token'=>'nullable|string']);$u=$r->attributes->get('app_user');$x=Device::updateOrCreate(['user_id'=>$u->id,'device_id'=>$d['device_id']],$d+['last_seen_at'=>now(),'revoked_at'=>null]);return response()->json(['ok'=>true,'device'=>$x]);} public function revoke(Request $r,string $deviceId){$u=$r->attributes->get('app_user');$x=Device::where('user_id',$u->id)->where('device_id',$deviceId)->firstOrFail();$x->update(['revoked_at'=>now(),'fcm_token'=>null]);return response()->json(['ok'=>true]);} }
